<script setup>
import {ref,computed,onMounted,nextTick,watch,onUnmounted} from 'vue';
import {LayoutDashboard,ClipboardList,Users,ChartNoAxesCombined,Settings,ArrowUpRight,ArrowRight,ChevronDown,ChevronLeft,ChevronRight,Plus,Download,Search,LogOut,Check,CheckCircle2,Clock3,FileCheck2,ScanLine,ExternalLink,GripVertical,Trash2,Copy,Save,X,ShieldCheck,Menu,Link,AlertCircle} from 'lucide-vue-next';
import {api} from './api';
import Preview from './Preview.vue';
const isPreview=location.pathname.startsWith('/preview');
const user=ref(null), loading=ref(true), busy=ref(false),error=ref(''),toast=ref(''),nav=ref('overview'),mobileMenu=ref(false);
const username=ref('admin'),password=ref(''),surveys=ref([]),selected=ref(''),stats=ref(null),version=ref(''),system=ref(null),editor=ref(null),search=ref(''),records=ref({rows:[],total:0,page:1,pageSize:20}),detail=ref(null);
const current=computed(()=>surveys.value.find(s=>s.id===selected.value));
const menu=[{id:'overview',text:'数据概览',icon:LayoutDashboard},{id:'surveys',text:'问卷管理',icon:ClipboardList},{id:'responses',text:'答题记录',icon:Users},{id:'analytics',text:'统计分析',icon:ChartNoAxesCombined}];
const navTitle=computed(()=>[...menu,{id:'settings',text:'应用设置'}].find(n=>n.id===nav.value)?.text);
const today=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());
const trend=computed(()=>{const rows=stats.value?.trend || [];if(!rows.length)return [];const max=Math.max(...rows.map(r=>r.count),1);return rows.map((r,i)=>({...r,x:rows.length===1?350:32+i*636/(rows.length-1),y:148-r.count/max*110}));});
const trendLine=computed(()=>trend.value.map(p=>`${p.x},${p.y}`).join(' '));
const notify=text=>{toast.value=text;setTimeout(()=>toast.value='',3500);};
async function run(task){error.value='';busy.value=true;try{await task();}catch(e){error.value=e.message;if(e.status===401)user.value=null;}finally{busy.value=false;}}
async function refresh(){surveys.value=await api('/admin/surveys');if(!selected.value || !surveys.value.some(s=>s.id===selected.value))selected.value=surveys.value[0]?.id || '';system.value=await api('/admin/system');await loadStats();}
async function loadStats(){if(!selected.value)return;stats.value=await api(`/admin/surveys/${selected.value}/stats${version.value?`?version=${version.value}`:''}`);if(nav.value==='responses')await loadRecords();}
async function changeSurvey(){version.value='';await run(loadStats);}
async function login(){await run(async()=>{user.value=await api('/admin/login',{method:'POST',body:{username:username.value,password:password.value}});password.value='';await refresh();});}
async function logout(){await run(async()=>{await api('/admin/logout',{method:'POST'});user.value=null;});}
async function go(id){nav.value=id;mobileMenu.value=false;error.value='';if(id==='responses')await run(()=>loadRecords(1));}
async function loadRecords(page=1){if(!selected.value)return;const q=new URLSearchParams({page:String(page),search:search.value});if(version.value)q.set('version',version.value);records.value=await api(`/admin/surveys/${selected.value}/responses?${q}`);}
function startEdit(s){editor.value=JSON.parse(JSON.stringify(s || {title:'新建问卷',description:'',status:'draft',questions:[{id:crypto.randomUUID(),title:'',type:'single',required:true,options:[{id:'o1',text:''},{id:'o2',text:''}]},{id:'phone',title:'手机号',type:'phone',required:true,options:[]}],completion:current.value?.completion || {heading:'感谢您的参与！',welcome:'',venue:'',sessions:[]}}));}
function addOption(q){q.options.push({id:crypto.randomUUID(),text:''});}
function addQuestion(){editor.value.questions.push({id:crypto.randomUUID(),title:'',type:'single',required:true,options:[{id:'o1',text:''},{id:'o2',text:''}]});}
function moveQuestion(i,delta){const a=editor.value.questions;if(i+delta<0||i+delta>=a.length)return;[a[i],a[i+delta]]=[a[i+delta],a[i]];}
async function saveSurvey(){await run(async()=>{const s=editor.value;const body={...s,questions:s.questions.map(q=>({...q,options:['text','phone'].includes(q.type)?[]:q.options}))};const result=await api(`/admin/surveys${s.id?'/'+s.id:''}`,{method:s.id?'PUT':'POST',body});selected.value=s.id || result.id;version.value='';editor.value=null;await refresh();notify('问卷已保存');});}
async function duplicate(s){await run(async()=>{const result=await api('/admin/surveys',{method:'POST',body:{...s,title:s.title+'（副本）',status:'draft'}});selected.value=result.id;version.value='';await refresh();notify('已复制为草稿');});}
async function setStatus(s,status){await run(async()=>{await api('/admin/surveys/'+s.id,{method:'PUT',body:{...s,status}});await refresh();notify(status==='published'?'问卷已发布':'问卷已关闭');});}
async function download(){await run(async()=>{const response=await fetch(`/api/admin/surveys/${selected.value}/export${version.value?'?version='+version.value:''}`);if(!response.ok){const data=await response.json();throw new Error(data.error);}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=`华堂宁问卷调查${version.value?'_V'+version.value:''}_${new Date().toISOString().slice(0,10)}.xlsx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('Excel 已导出');});}
function answerText(row,q){const a=row.answers[q.id];return ['text','phone'].includes(q.type)?(a || '未填写'):q.options.filter(o=>Array.isArray(a)?a.includes(o.id):a===o.id).map(o=>o.text).join('；') || '未填写';}
const date=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
let returnFocus;
watch([editor,detail],async([e,d])=>{document.body.style.overflow=e||d?'hidden':'';if(e||d){returnFocus=document.activeElement;await nextTick();document.querySelector('.modal button')?.focus();}else returnFocus?.focus();});
function modalKeyboard(event){if(!editor.value&&!detail.value)return;if(event.key==='Escape'){editor.value=null;detail.value=null;}if(event.key==='Tab'){const elements=[...document.querySelectorAll('.modal button:not([disabled]),.modal input,.modal select,.modal textarea,.modal a[href]')];const first=elements[0],last=elements.at(-1);if(event.shiftKey && document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
document.addEventListener('keydown',modalKeyboard);
onUnmounted(()=>{document.removeEventListener('keydown',modalKeyboard);document.body.style.overflow='';});
onMounted(async()=>{if(isPreview)return;try{user.value=await api('/admin/me');await refresh();}catch(e){if(e.status!==401)error.value=e.message;}finally{loading.value=false;}});
</script>

<template>
  <Preview v-if="isPreview" />
  <main v-else-if="loading" class="boot" aria-live="polite">正在加载管理后台…</main>
  <main v-else-if="!user" class="login-page">
    <div class="login-art"><img src="/assets/brand-strip.png" alt="华领医药 华堂宁"/><div><span class="eyebrow">HUATANGNING · SURVEY</span><h1>每一份回答，<br>都是更进一步的了解。</h1><p>华堂宁问卷调查 · 管理工作台</p></div><img class="login-science" src="/assets/survey-footer.jpg" alt=""/></div>
    <form class="login-form" @submit.prevent="login"><span class="small-brand">华堂宁<span>问卷调查</span></span><h2>欢迎回来</h2><p class="muted">登录管理后台，查看问卷与答题数据</p><label>管理员账号<input v-model="username" autocomplete="username" required/></label><label>登录密码<input v-model="password" type="password" autocomplete="current-password" required/></label><div v-if="error" class="error" role="alert">{{error}}</div><button class="primary" :disabled="busy">{{busy?'正在登录…':'登录工作台'}}<ArrowRight :size="18"/></button><small><ShieldCheck :size="15"/>管理员专属入口，答题请通过微信小程序参与</small></form>
  </main>
  <div v-else class="admin-shell">
    <aside class="sidebar" :class="{open:mobileMenu}">
      <a class="brand" href="/admin/"><span class="brand-mark">H<span>·</span></span><span>华堂宁<small>问卷管理平台</small></span></a>
      <div class="sidebar-label">工作空间</div>
      <nav aria-label="管理后台导航"><button v-for="item in menu" :key="item.id" :class="{active:nav===item.id}" @click="go(item.id)"><component :is="item.icon" :size="19"/>{{item.text}}<span v-if="item.id==='surveys'" class="nav-count">{{surveys.length}}</span></button></nav>
      <div class="sidebar-bottom"><div class="app-card"><span class="app-card-icon"><ScanLine :size="21"/></span><strong>华堂宁问卷调查</strong><p>微信小程序</p><a href="/preview/" target="_blank" rel="noopener">查看设计预览<ArrowUpRight :size="15"/></a></div><button class="settings-nav" :class="{active:nav==='settings'}" @click="go('settings')"><Settings :size="19"/>应用设置</button><div class="admin-account"><span class="avatar">管</span><div><strong>{{user.username}}</strong><small>管理员</small></div><button class="icon-button" aria-label="退出登录" @click="logout"><LogOut :size="17"/></button></div></div>
    </aside>
    <div class="main-area"><header class="topbar"><div class="breadcrumb"><button class="icon-button menu-toggle" aria-label="打开导航" @click="mobileMenu=!mobileMenu"><Menu :size="20"/></button><span>工作空间</span><ChevronRight :size="14"/><strong>{{navTitle}}</strong></div><div class="topbar-right"><span class="status-dot"></span>管理工作台<span class="topbar-divider"></span><span class="avatar small">管</span></div></header>
      <main class="content">
        <div class="page-heading"><div><p class="eyebrow">{{nav==='overview'?'WORKSPACE OVERVIEW':nav==='surveys'?'QUESTIONNAIRES':nav==='responses'?'RESPONSE RECORDS':nav==='analytics'?'SURVEY ANALYTICS':'APPLICATION SETTINGS'}}</p><h1>{{navTitle}}<span v-if="nav==='overview'" class="greeting-dot">.</span></h1><p class="muted">{{nav==='overview'?'每一份回答都清晰可见，了解问卷的最新动态。':nav==='surveys'?'管理调查内容，让每一个问题都有意义。':nav==='responses'?'查看每一份真实答卷，支持按昵称、手机号或 OpenID 检索。':nav==='analytics'?'从回答中发现洞察，按问卷版本查看选项分布。':'查看微信接入与线上部署的准备情况。'}}</p></div><div class="heading-actions"><span v-if="nav==='overview'" class="date-text">{{today}}</span><button v-if="nav==='surveys'" class="primary" @click="startEdit()"><Plus :size="17"/>新建问卷</button><button v-else-if="nav!=='settings'" class="outline" :disabled="!current || busy" @click="download"><Download :size="16"/>导出 Excel</button></div></div>
        <div v-if="error" class="error" role="alert"><AlertCircle :size="18"/>{{error}}<button aria-label="关闭错误提示" @click="error=''"><X :size="16"/></button></div>
        <div v-if="system && !system.wechatReady" class="setup-banner"><span><Link :size="16"/>微信小程序待接入<span class="banner-sub">填写 AppID 与 AppSecret 后，可启用真实微信登录。</span></span><button @click="go('settings')">查看配置<ArrowRight :size="14"/></button></div>
        <template v-if="nav==='overview' || nav==='analytics' || nav==='responses'">
          <div class="survey-selector"><div><span class="selector-caption">当前问卷</span><select v-model="selected" aria-label="选择问卷" @change="changeSurvey"><option v-for="s in surveys" :value="s.id">{{s.title}}</option></select><span v-if="current" class="badge" :class="current.status">{{({published:'收集中',draft:'草稿',closed:'已结束'})[current.status]}}</span></div><label class="version-label">统计版本<select v-model="version" @change="run(loadStats)"><option value="">当前 V{{current?.version}}</option><option v-for="v in stats?.versions.filter(v=>v.version!==current?.version)" :value="v.version">V{{v.version}}（{{v.count}} 份）</option></select></label></div>
        </template>
        <template v-if="(nav==='overview'||nav==='analytics') && stats">
          <div class="metric-grid"><article class="metric"><div><span>累计有效答卷</span><span class="metric-icon teal"><FileCheck2 :size="19"/></span></div><strong>{{stats.totalAll.toLocaleString()}}<small>份</small></strong><p>已提交并成功保存的答卷</p></article><article class="metric"><div><span>参与人数</span><span class="metric-icon blue"><Users :size="19"/></span></div><strong>{{stats.started.toLocaleString()}}<small>人</small></strong><p>已绑定微信并开始填写</p></article><article class="metric"><div><span>问卷完成率</span><span class="metric-icon amber"><ChartNoAxesCombined :size="19"/></span></div><strong>{{stats.completionRate}}<small>%</small></strong><p>有效答卷 / 开始填写人数</p></article><article class="metric"><div><span>平均答题用时</span><span class="metric-icon violet"><Clock3 :size="19"/></span></div><strong>{{stats.averageDuration}}<small>秒</small></strong><p>所选版本 · {{stats.total}} 份答卷</p></article></div>
          <div v-if="nav==='overview'" class="overview-grid"><section class="panel trend-panel"><div class="panel-heading"><div><h2>答卷收集趋势</h2><p>按北京时间统计每日提交量 · V{{stats.version}}</p></div><span class="subtle-tag">最近 14 个有提交日</span></div><div class="chart" v-if="trend.length"><div class="chart-legend"><i></i>有效答卷</div><svg viewBox="0 0 700 180" role="img" :aria-label="stats.trend.map(r=>r.day+'：'+r.count+'份').join('；')"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#158b88" stop-opacity=".18"/><stop offset="100%" stop-color="#158b88" stop-opacity="0"/></linearGradient></defs><path v-for="y in [38,93,148]" :d="`M32 ${y}H668`" stroke="#edf0f2" stroke-dasharray="4 4"/><polygon v-if="trend.length>1" :points="`32,160 ${trendLine} 668,160`" fill="url(#chart-fill)"/><polyline v-if="trend.length>1" :points="trendLine" fill="none" stroke="#14878b" stroke-width="2.5"/><circle v-for="p in trend" :cx="p.x" :cy="p.y" r="4" fill="#14878b"><title>{{p.day}}：{{p.count}} 份</title></circle><text v-for="(p,i) in trend.filter((_,i)=>i%Math.max(1,Math.ceil(trend.length/5))===0)" :x="p.x" y="178" text-anchor="middle" fill="#7d8990" font-size="11">{{p.day.slice(5)}}</text></svg></div><div v-else class="chart-empty"><ChartNoAxesCombined :size="32"/><strong>等待第一份回答</strong><p>问卷发布后，答卷趋势将在这里呈现</p></div></section><section class="panel survey-summary"><div class="panel-heading"><h2>问卷概况</h2><ClipboardList :size="18"/></div><span class="summary-eyebrow">HUATANGNING SURVEY</span><h3>{{current?.title}}</h3><div class="summary-rows"><span>题目数量<strong>{{current?.questions.length}} 题</strong></span><span>当前版本<strong>V{{current?.version}}</strong></span><span>参与方式<strong>微信绑定后填写</strong></span><span>重复提交<strong>每人限提交一次</strong></span></div><button class="text-button" @click="startEdit(current)">管理此问卷<ArrowUpRight :size="16"/></button></section></div>
          <section class="panel distribution"><div class="panel-heading"><div><h2>题目回答分布</h2><p>V{{stats.version}} · {{stats.total}} 份答卷，支持多选的题目占比之和可能超过 100%</p></div><button v-if="nav==='overview'" class="text-button" @click="go('analytics')">全部统计<ArrowRight :size="15"/></button></div><div class="question-stat-grid"><article v-for="(q,i) in (nav==='overview'?stats.questions.slice(0,2):stats.questions)" :key="q.id" class="question-stat"><div class="question-stat-heading"><span class="number-label">{{String(i+1).padStart(2,'0')}}</span><span class="subtle-tag">{{({single:'单选题',multiple:'多选题',text:'文本题',phone:'手机号'})[q.type]}}</span><span class="answered-count">{{q.answered}} 人作答</span></div><h3>{{q.title}}</h3><div v-if="!['text','phone'].includes(q.type)" class="option-stats"><div v-for="(o,j) in q.options" :key="o.id"><div class="option-stat-label"><span>{{String.fromCharCode(65+j)}}. {{o.text}}</span><strong>{{stats.total?Math.round(o.count/stats.total*100):0}}%<small>{{o.count}} 人</small></strong></div><div class="bar-track"><span :style="{width:(stats.total?o.count/stats.total*100:0)+'%'}"></span></div></div></div><button v-else class="outline" @click="go('responses')">查看文本答卷<ArrowRight :size="16"/></button></article></div></section>
        </template>
        <template v-if="nav==='surveys'"><section class="panel survey-list"><div class="panel-heading"><h2>全部问卷<span class="count-pill">{{surveys.length}}</span></h2><span class="muted">每份问卷需保留一道必填手机号题</span></div><article v-for="s in surveys" class="survey-list-item"><span class="survey-list-icon"><ClipboardList :size="24"/></span><div class="survey-list-main"><div><h3>{{s.title}}</h3><span class="badge" :class="s.status">{{({published:'收集中',draft:'草稿',closed:'已结束'})[s.status]}}</span></div><p>{{s.questions.length}} 道题<span>·</span>{{s.response_count}} 份答卷<span>·</span>V{{s.version}}<span>·</span>更新于 {{date(s.updated_at)}}</p></div><div class="row-actions"><button class="outline" @click="startEdit(s)">编辑问卷</button><button class="icon-button" aria-label="复制问卷" @click="duplicate(s)"><Copy :size="17"/></button><button class="text-button" :disabled="busy" @click="setStatus(s,s.status==='published'?'closed':'published')">{{s.status==='published'?'结束收集':'发布问卷'}}</button></div></article></section><div class="info-note"><ShieldCheck :size="17"/>同一微信用户对每份问卷限提交一次。已提交答卷保留原题目快照，不受后续编辑影响。</div></template>
        <section v-if="nav==='responses'" class="panel records-panel"><div class="panel-heading"><h2>答题记录<span class="count-pill">{{records.total}}</span></h2><form class="search-form" @submit.prevent="run(()=>loadRecords(1))"><Search :size="16"/><input v-model="search" placeholder="搜索昵称、手机号、OpenID" aria-label="搜索答题记录"/><button>搜索</button></form></div><div class="table-scroll"><table><thead><tr><th>参与用户</th><th>微信 OpenID</th><th>手机号</th><th>问卷版本</th><th>提交时间</th><th>用时</th><th>操作</th></tr></thead><tbody><tr v-for="row in records.rows" :key="row.id"><td><span class="table-user"><img v-if="row.avatar" :src="row.avatar" alt=""/><span v-else class="avatar small">{{row.nickname.slice(0,1)}}</span><strong>{{row.nickname}}</strong></span></td><td class="openid" :title="row.openid">{{row.openid}}</td><td>{{row.phone || '未填写'}}</td><td><span class="subtle-tag">V{{row.version}}</span></td><td>{{date(row.submitted_at)}}</td><td>{{row.duration_seconds}} 秒</td><td><button class="text-button" @click="detail=row">查看答卷<ArrowUpRight :size="14"/></button></td></tr></tbody></table><div v-if="!records.rows.length" class="empty-state"><Users :size="30"/><h3>{{search?'没有匹配的答卷':'还没有收到答卷'}}</h3><p>{{search?'请尝试其他昵称、手机号或 OpenID。':'用户完成微信绑定并提交问卷后，记录将显示在这里。'}}</p></div></div><div class="pagination"><span>共 {{records.total}} 条 · 每页 20 条</span><div><button class="icon-button" :disabled="records.page<=1 || busy" aria-label="上一页" @click="run(()=>loadRecords(records.page-1))"><ChevronLeft :size="17"/></button><span>{{records.page}} / {{Math.max(1,Math.ceil(records.total/20))}}</span><button class="icon-button" :disabled="records.page*20>=records.total || busy" aria-label="下一页" @click="run(()=>loadRecords(records.page+1))"><ChevronRight :size="17"/></button></div></div></section>
        <template v-if="nav==='settings' && system"><section class="panel settings-panel"><div class="panel-heading"><div><h2>微信小程序接入</h2><p>应用名称：华堂宁问卷调查</p></div><span class="badge" :class="system.wechatReady?'published':'draft'">{{system.wechatReady?'已配置':'待配置'}}</span></div><div class="setting-row"><div><strong>微信登录</strong><p>服务端通过 wx.login 临时凭证核验 OpenID</p></div><span>{{system.wechatReady?'AppID / AppSecret 已配置':'等待申请小程序账号'}}</span></div><div class="setting-row"><div><strong>手机号收集</strong><p>个人小程序：在问卷内手动填写并设为必填</p></div><span>手动填写 · 格式校验</span></div><div class="setting-row"><div><strong>数据存储</strong><p>问卷、会话与缩略头像持久化保存到数据库</p></div><span>{{system.database==='mysql'?'云托管 MySQL':'本地 SQLite'}}</span></div><div class="setting-row"><div><strong>运行环境</strong><p>生产环境禁止使用本地体验身份</p></div><span>{{system.production?'生产环境':'本地开发'}}{{system.devLogin?' · 体验登录已开启':''}}</span></div><div class="setting-row"><div><strong>访问地址</strong><p>上线需要 HTTPS 域名并配置小程序 request 合法域名</p></div><span>{{system.publicOrigin}}</span></div></section><section class="panel deploy-checklist"><h2>上线准备</h2><ol><li><strong>注册微信小程序</strong><p>申请 AppID，完成主体认证及所需类目与备案。</p></li><li><strong>准备微信云托管及 MySQL</strong><p>沿用仓库流水线部署，按说明填写数据库、微信和后台环境变量。</p></li><li><strong>配置隐私保护指引</strong><p>声明实际收集的昵称、头像、OpenID、问卷答案及手动填写的手机号。</p></li><li><strong>真机验收与提交审核</strong><p>微信开发者工具导入 miniprogram，核验登录、绑定、提交及导出后上传审核。</p></li></ol><p class="info-note"><ShieldCheck :size="17"/>AppSecret 只保存在服务器环境变量中。</p></section></template>
        <footer class="page-footer"><span>华堂宁问卷调查 · 管理工作台</span><span><ShieldCheck :size="13"/>数据仅供授权管理员查看</span></footer>
      </main>
    </div>
    <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="18"/>{{toast}}</div>
    <div v-if="editor" class="modal-backdrop"><section class="editor modal" role="dialog" aria-modal="true" aria-labelledby="editor-title"><header class="modal-heading"><div><span class="eyebrow">QUESTIONNAIRE EDITOR</span><h2 id="editor-title">{{editor.id?'编辑问卷':'新建问卷'}}</h2></div><button class="icon-button" aria-label="关闭编辑" @click="editor=null"><X :size="21"/></button></header><form @submit.prevent="saveSurvey"><div class="editor-body"><div class="editor-meta"><label>问卷名称<input v-model="editor.title" required maxlength="150"/></label><label>问卷说明<textarea v-model="editor.description" maxlength="2000" rows="2"></textarea></label><label>收集状态<select v-model="editor.status"><option value="draft">草稿</option><option value="published">发布并收集</option><option value="closed">结束收集</option></select></label></div><div class="editor-section-heading"><h3>题目内容</h3><span>{{editor.questions.length}} 道题</span></div><article v-for="(q,i) in editor.questions" :key="q.id" class="question-editor"><div class="question-editor-toolbar"><span class="number-label">{{String(i+1).padStart(2,'0')}}</span><select v-model="q.type" :aria-label="'第'+(i+1)+'题类型'"><option value="single">单选题</option><option value="multiple">多选题</option><option value="text">文本题</option><option value="phone">手机号（必填）</option></select><label class="checkbox-label"><input type="checkbox" v-model="q.required"/>必填</label><div class="question-tools"><button type="button" class="icon-button" :disabled="i===0" aria-label="题目上移" @click="moveQuestion(i,-1)">↑</button><button type="button" class="icon-button" :disabled="i===editor.questions.length-1" aria-label="题目下移" @click="moveQuestion(i,1)">↓</button><button type="button" class="icon-button danger" :disabled="editor.questions.length===1" aria-label="删除题目" @click="editor.questions.splice(i,1)"><Trash2 :size="16"/></button></div></div><label>题目<textarea v-model="q.title" rows="2" required maxlength="1000"></textarea></label><div v-if="!['text','phone'].includes(q.type)" class="editor-options"><div v-for="(o,j) in q.options" :key="o.id"><span>{{String.fromCharCode(65+j)}}</span><input v-model="o.text" :aria-label="'第'+(i+1)+'题选项'+String.fromCharCode(65+j)" required maxlength="500"/><button class="icon-button" type="button" :disabled="q.options.length<=2" aria-label="删除选项" @click="q.options.splice(j,1)"><X :size="15"/></button></div><button type="button" class="text-button" :disabled="q.options.length>=26" @click="addOption(q)"><Plus :size="15"/>添加选项</button></div></article><button type="button" class="add-question" :disabled="editor.questions.length>=100" @click="addQuestion"><Plus :size="18"/>添加题目</button><div class="editor-section-heading"><h3>提交成功页</h3><span>沿用 PSD 会议邀请视觉</span></div><div class="editor-meta"><label>感谢语<input v-model="editor.completion.heading" required maxlength="100"/></label><label>欢迎语<input v-model="editor.completion.welcome" maxlength="200"/></label><label>会场<input v-model="editor.completion.venue" maxlength="200"/></label><div v-for="(session,i) in editor.completion.sessions" class="session-editor"><label>场次时间<input v-model="session.time" maxlength="100"/></label><label>场次主题<input v-model="session.title" maxlength="200"/></label><button type="button" class="icon-button danger" aria-label="移除场次" @click="editor.completion.sessions.splice(i,1)"><Trash2 :size="16"/></button></div><button type="button" class="text-button" :disabled="editor.completion.sessions.length>=10" @click="editor.completion.sessions.push({time:'',title:''})"><Plus :size="15"/>添加场次</button></div><div v-if="error" class="error" role="alert">{{error}}</div></div><footer class="editor-footer"><span>保存将保留已有答卷对应的版本</span><button type="button" class="outline" @click="editor=null">取消</button><button class="primary" :disabled="busy"><Save :size="16"/>{{busy?'保存中…':'保存问卷'}}</button></footer></form></section></div>
    <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="response-detail modal" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="modal-heading"><div><span class="eyebrow">RESPONSE DETAIL</span><h2 id="detail-title">{{detail.nickname}} 的答卷</h2></div><button class="icon-button" aria-label="关闭答卷详情" @click="detail=null"><X :size="21"/></button></header><div class="detail-body"><p class="muted">V{{detail.version}} · {{date(detail.submitted_at)}} · 用时 {{detail.duration_seconds}} 秒</p><article v-for="(q,i) in detail.snapshot.questions"><h3>{{i+1}}. {{q.title}}</h3><p>{{answerText(detail,q)}}</p></article></div></section></div>
  </div>
</template>
